INSERT INTO `notices` VALUES (1,'Welcome to Anka','Results, attendance and insights now live in one place. Use the public Result Search with your symbol number, or verify a marksheet with its code.','all',NULL,'2026-11-04 09:24:00'),(2,'80% attendance rule','Students need at least 80% attendance to be eligible for the term-end examination. Check your attendance page regularly.','student',NULL,'2026-11-04 09:24:00'),(3,'Marks entry deadline','Teachers: please complete internal and external marks entry for the current term before the board meeting. CSV import is available on the Marks page.','teacher',NULL,'2026-11-04 09:24:00');
