/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `results` (
  `id` int NOT NULL AUTO_INCREMENT,
  `student_id` int NOT NULL,
  `semester` tinyint NOT NULL,
  `exam_year` smallint NOT NULL,
  `total_marks` decimal(7,2) NOT NULL DEFAULT '0.00',
  `full_marks` decimal(7,2) NOT NULL DEFAULT '0.00',
  `percentage` decimal(5,2) NOT NULL DEFAULT '0.00',
  `total_credits` decimal(4,1) NOT NULL DEFAULT '0.0',
  `gpa` decimal(3,2) NOT NULL DEFAULT '0.00',
  `grade` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'F',
  `division` varchar(24) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `backpapers` tinyint NOT NULL DEFAULT '0' COMMENT 'subjects cleared through back papers',
  `status` enum('pass','fail','incomplete') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'incomplete',
  `class_rank` int DEFAULT NULL,
  `verify_code` char(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `published` tinyint(1) NOT NULL DEFAULT '0',
  `published_at` timestamp NULL DEFAULT NULL,
  `calculated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_result` (`student_id`,`semester`,`exam_year`),
  UNIQUE KEY `verify_code` (`verify_code`),
  KEY `idx_rank` (`semester`,`exam_year`,`class_rank`),
  CONSTRAINT `results_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=345 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
